commands:
node -e '
const fs = require("node:fs");
const rawLines = fs.readFileSync("input/incident.jsonl","utf8").split("\n");
const records = [];
rawLines.forEach((text,index)=>{ if(text.trim().length===0) return; records.push({line:index+1, record: JSON.parse(text)}); });
function categoriseKey(key){
  if (/pool|capacity|concurrency|max/.test(key)) return "capacity_misconfiguration";
  if (/retry|backoff|attempt/.test(key)) return "retry_amplification";
  if (/credential|token|secret/.test(key)) return "credential_expiry";
  if (/upstream|dependency|endpoint/.test(key)) return "dependency_outage";
  return "code_defect";
}
const roleByLine = new Map();
const triggers = [];
for (const {line, record} of records) {
  if (record.event === "config_applied" && typeof record.from === "number" && typeof record.to === "number" && record.to < record.from) {
    roleByLine.set(line, "trigger"); triggers.push({line, key: String(record.key ?? "")}); continue;
  }
  if (record.event === "retry_scheduled" && record.backoff_ms === 0) { roleByLine.set(line, "amplification"); continue; }
  if (record.level === "fatal") { roleByLine.set(line, "failure"); }
}
triggers.sort((a,b)=>a.line-b.line);
const earliest = triggers[0];
const rootCause = earliest ? {line: earliest.line, category: categoriseKey(earliest.key)} : null;
const deliverable = JSON.parse(fs.readFileSync("analysis/timeline.json","utf8"));
const found = new Set(deliverable.events.map(e=>e.line));
const missing = [...roleByLine.entries()].filter(([l])=>!found.has(l)).map(([l,r])=>`${l}(${r})`);
console.log("derived_role_count="+roleByLine.size);
console.log("missing_from_deliverable="+JSON.stringify(missing));
console.log("derived_rootCause="+JSON.stringify(rootCause));
console.log("deliverable_rootCause="+JSON.stringify(deliverable.rootCause));
console.log("deliverable_complete="+deliverable.complete);
'
